import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Kits Are Curated Plugin Lists, Not Implementations","description":"","frontmatter":{"title":"Kits Are Curated Plugin Lists, Not Implementations","type":"adr","date":"2026-09-02T00:00:00.000Z","status":"proposed","status_note":"Proposed — kits curate plugins; composition is dynamic."},"headers":[],"relativePath":"handl/project/adrs/0039-kits-are-curated-plugin-lists.md","filePath":"vendored/handl/project/adrs/0039-kits-are-curated-plugin-lists.md"}`),a={name:`handl/project/adrs/0039-kits-are-curated-plugin-lists.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0039-kits-are-curated-plugin-lists-not-implementations" tabindex="-1">ADR-0039: Kits Are Curated Plugin Lists, Not Implementations <a class="header-anchor" href="#adr-0039-kits-are-curated-plugin-lists-not-implementations" aria-label="Permalink to “ADR-0039: Kits Are Curated Plugin Lists, Not Implementations”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>A kit is a curated list of plugins, not an implementation.</strong> It selects and orders plugins; it does not provide operations itself.</li><li><strong>Composition is dynamic</strong>: a kit is resolved when the host loads it, not compiled into the binary.</li><li><strong>Plugins offer capabilities; kits only curate them</strong> — the capability belongs to the plugin, never to the kit.</li><li><strong>Naming principle</strong>: a kit is named for the surface it curates (<code>kit-canonical</code>, <code>kit-type</code>), not for the repo or host that uses it.</li><li><strong>Migration is four phases</strong>: thin <code>kit-canonical</code>, separate kits from hosts, make <code>kit-type</code> a real kit, update consumers.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>Kits were implementations, so replacing a plugin meant editing the kit and rebuilding; the same plugin could not be curated differently by two hosts. Curation as data makes composition a load-time choice and keeps capabilities with their plugins.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Kits that implement operations</strong> — that is the current coupling.</li><li><strong>Static dispatch baked into the kit</strong> — kits are resolved, not compiled in.</li><li><strong>Per-host kit copies</strong> — one kit, curated by many hosts.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Kits become small data; a host chooses a kit, a kit chooses plugins.</li><li>Dynamic loading is required; failures surface at load time.</li><li>Naming discipline keeps the surface obvious.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>kit-canonical/</code>, <code>kit-prelude/</code> — the kit manifests.</li><li><code>crates/plugin-ext-kit/</code> — curation and loading.</li><li>Host tests that load a kit and exercise an op.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+The architecture, dynamic composition, naming and the four phases: +<a href="./../design/0039-kits-are-curated-plugin-lists.html"><code>design/0039-kits-are-curated-plugin-lists.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};